import { useState } from 'react';
import { useLocation, useNavigate, Link } from 'react-router-dom';
import { motion } from 'framer-motion';
import { setPassword } from '../api';

export default function SetPassword() {
  const [form, setForm] = useState({ password: '', confirmPassword: '' });
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const location = useLocation();
  const navigate = useNavigate();

  const contact = location.state?.contact || '';

  const handleChange = (e) => setForm({ ...form, [e.target.name]: e.target.value });

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (form.password !== form.confirmPassword) {
      setError('Passwords do not match');
      return;
    }
    if (!contact) {
      setError('Contact is missing. Please start over.');
      return;
    }
    setError('');
    setLoading(true);
    try {
      await setPassword({ contact, password: form.password });
      navigate('/login', { state: { message: 'Account created. Please login.' } });
    } catch (err) {
      setError(err.response?.data?.error || 'Failed to set password');
    } finally {
      setLoading(false);
    }
  };

  return (
    <motion.div initial={{ opacity: 0, y: 15 }} animate={{ opacity: 1, y: 0 }} className="max-w-xl mx-auto mt-16 bg-slate-800 rounded-xl shadow-lg p-8">
      <h1 className="text-2xl font-bold mb-4">Set Your Password</h1>
      <p className="text-sm text-slate-300 mb-4">Create a password for {email}.</p>
      <form onSubmit={handleSubmit} className="space-y-4">
        <input type="password" name="password" value={form.password} onChange={handleChange} placeholder="Password" className="w-full p-3 rounded-lg bg-slate-700" required />
        <input type="password" name="confirmPassword" value={form.confirmPassword} onChange={handleChange} placeholder="Confirm Password" className="w-full p-3 rounded-lg bg-slate-700" required />
        {error && <p className="text-red-400">{error}</p>}
        <button type="submit" disabled={loading} className="w-full py-3 bg-emerald-600 hover:bg-emerald-500 rounded-lg font-semibold transition">
          {loading ? 'Creating Account...' : 'Create Account'}
        </button>
      </form>
      <p className="mt-4 text-sm text-slate-300">Go back to <Link to="/signup" className="text-cyan-300">Signup</Link></p>
    </motion.div>
  );
}
